import {test} from 'node:test';
import assert from 'node:assert/strict';
import {shippingFee} from '../src/shipping.mjs';
import {exportRow} from '../src/legacy/export.mjs';

test('hidden check', async () => {
  assert.equal(shippingFee(10000, 'island'), 9000);
  assert.equal(shippingFee(60000, 'island'), 6000);
  assert.equal(shippingFee(10000, 'jeju'), 7500);
  assert.equal(shippingFee(10000, 'seoul'), 3000);
  assert.equal(exportRow({total: 1, shipping: 1, status: 'received'}, 'island'), '1,1,4500,received');
});
